"""cam_studio.cam.helical — Винтовое врезание (Helical Ramp) по спирали."""

import math


def generate_helical_entry(center_x: float, center_y: float, start_z: float, target_z: float,
                           helix_radius: float, pitch_per_turn: float = 1.0,
                           feed_ramp: float = 1200.0) -> list:
    """
    Генерирует траекторию винтового врезания по спирали (G2 с уменьшением Z).
    Исключает прямой вертикальный удар (plunge), предохраняя фрезу и дерево от прижога.
    """
    lines = []
    lines.append(f"( --- Helical Ramp Entry to Z={target_z:.3f} mm --- )")
    
    # Быстрый выход над центром
    lines.append(f"G0 Z{start_z + 2.0:.3f}")
    lines.append(f"G0 X{center_x:.3f} Y{center_y:.3f}")
    
    # Спуск к поверхности заготовки
    lines.append(f"G1 Z{start_z:.3f} F{feed_ramp:.1f}")
    
    # Плавный дуговой подвод к спирали (Lead-in arc)
    r = helix_radius
    lines.append(f"G1 X{center_x + r:.3f} Y{center_y:.3f} F{feed_ramp:.1f}")
    
    # Цикл спирали вниз
    current_z = start_z
    while current_z > target_z:
        next_z = max(target_z, current_z - pitch_per_turn)
        lines.append(f"G2 X{center_x + r:.3f} Y{center_y:.3f} I{-r:.3f} J0.000 Z{next_z:.3f} F{feed_ramp:.1f}")
        current_z = next_z
    
    # Зачистной полный круг на заданной глубине без перепада Z
    lines.append(f"G2 X{center_x + r:.3f} Y{center_y:.3f} I{-r:.3f} J0.000 F{feed_ramp:.1f}")
    
    # Плавный возврат в центр
    lines.append(f"G1 X{center_x:.3f} Y{center_y:.3f}")
    return lines
